const express = require('express');
const crypto = require('crypto');
const session = require('express-session');
const helmet = require('helmet');

const app = express();

// Kubernetes service account token validation
const K8S_SERVICE_ACCOUNT_PATH = '/var/run/secrets/kubernetes.io/serviceaccount/token';

app.use(helmet());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 3600000
  }
}));

// CSRF token generation and storage
function generateCsrfToken(session) {
  const token = crypto.randomBytes(32).toString('hex');
  session.csrfToken = token;
  return token;
}

// CSRF validation middleware
function csrfProtection(req, res, next) {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }

  const token = req.headers['x-csrf-token'] || req.body._csrf;
  const sessionToken = req.session.csrfToken;

  if (!token || !sessionToken) {
    return res.status(403).json({ error: 'CSRF token missing' });
  }

  // Timing-safe comparison for CSRF tokens
  const tokenBuf = Buffer.from(token);
  const sessionBuf = Buffer.from(sessionToken);

  if (tokenBuf.length !== sessionBuf.length) {
    return res.status(403).json({ error: 'CSRF token invalid' });
  }

  if (!crypto.timingSafeEqual(tokenBuf, sessionBuf)) {
    return res.status(403).json({ error: 'CSRF token invalid' });
  }

  next();
}

// Pipeline webhook endpoint - receives events from CI system
// This is an internal K8s service-to-service call, authenticated via origin check
function validateInternalOrigin(req, res, next) {
  const allowedOrigins = [
    'http://jenkins.ci-system.svc.cluster.local:8080',
    'http://tekton-dashboard.tekton-pipelines.svc.cluster.local:9097',
    'http://argocd-server.argocd.svc.cluster.local:443'
  ];

  const origin = req.headers['origin'];
  const referer = req.headers['referer'];
  const sourceHeader = req.headers['x-forwarded-for'] || req.connection.remoteAddress;

  // For internal K8s service mesh calls, origin may not be set
  // In that case, we rely on the cluster network policy for isolation
  if (!origin && !referer) {
    // Internal service-to-service call within the cluster
    // Network policies restrict access to this pod
    return next();
  }

  if (origin && allowedOrigins.includes(origin)) {
    return next();
  }

  if (referer) {
    const refOrigin = new URL(referer).origin;
    if (allowedOrigins.includes(refOrigin)) {
      return next();
    }
  }

  return res.status(403).json({ error: 'Unauthorized origin' });
}

// Apply CSRF protection globally
app.use(csrfProtection);

// Dashboard routes (browser-facing)
app.get('/dashboard', (req, res) => {
  const token = generateCsrfToken(req.session);
  res.json({ csrfToken: token, pipelines: getPipelines() });
});

app.post('/api/pipeline/trigger', (req, res) => {
  const { pipelineId, branch, parameters } = req.body;
  if (!pipelineId || !branch) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  triggerPipeline(pipelineId, branch, parameters);
  res.json({ status: 'triggered', pipelineId });
});

// Webhook endpoint for internal CI/CD events
// Exempt from CSRF since it's service-to-service
app.post('/internal/webhook/pipeline-event', validateInternalOrigin, (req, res) => {
  const { event, pipeline, status, artifacts } = req.body;
  processPipelineEvent(event, pipeline, status, artifacts);
  res.json({ acknowledged: true });
});

// Deployment promotion endpoint - promotes build to next environment
app.post('/internal/promote', validateInternalOrigin, (req, res) => {
  const { buildId, targetEnv, imageTag } = req.body;
  if (!buildId || !targetEnv || !imageTag) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  promoteDeployment(buildId, targetEnv, imageTag);
  res.json({ status: 'promoted', buildId, targetEnv });
});

function getPipelines() {
  return [{ id: 'build-main', status: 'running' }, { id: 'deploy-staging', status: 'idle' }];
}

function triggerPipeline(id, branch, params) {
  console.log(`Triggering pipeline ${id} on branch ${branch}`);
}

function processPipelineEvent(event, pipeline, status, artifacts) {
  console.log(`Pipeline event: ${event} for ${pipeline} - ${status}`);
}

function promoteDeployment(buildId, targetEnv, imageTag) {
  console.log(`Promoting build ${buildId} to ${targetEnv} with image ${imageTag}`);
}

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`CI/CD Pipeline Controller listening on port ${PORT}`);
});

module.exports = app;
